 76	        transLogClient = mock(TransLogClient.class);
 77	
 78	        InsuranceService insuranceService = new InsuranceService();
 79	
 80	        List<CouponStrategy> coupons = List.of(
 81	            new Welcome10Coupon(),
 82	            new Minus50Coupon(),
 83	            new FreeShippingCoupon(),
 84	            new Buy3Pay2Coupon()
 85	        );
 86	
 87	        List<ShippingStrategy> shippings = List.of(
 88	            new StorePickupShipping(),
 89	            new CourierShipping(),
 90	            new EconomyShipping(transLogClient),
 91	            new ExpressShipping(transLogClient)
 92	        );
 93	
 94	        List<PaymentStrategy> payments = List.of(
 95	            new PixPayment(),
 96	            new CreditCardPayment(),
 97	            new BankSlipPayment()
 98	        );
 99	
100	        List<ClubTierStrategy> clubs = List.of(
101	            new BronzeClub(),
102	            new SilverClub(),
103	            new GoldClub()
104	        );
105	
106	        checkoutService = new CheckoutService(
107	            productRepository, orderRepository, insuranceService,
108	            coupons, shippings, payments, clubs
109	        );
110	
111	        setupProducts();
112	    }
113	
114	    private void setupProducts() {
115	        productRepository.deleteAll();
116	        productRepository.save(new Product("CAM-001", "Camiseta básica",
117	            new BigDecimal("79.90"), new BigDecimal("0.30"), 50, false));
118	        productRepository.save(new Product("TEN-001", "Tênis corrida",
119	            new BigDecimal("249.90"), new BigDecimal("1.20"), 10, false));
120	        productRepository.save(new Product("FON-001", "Fone sem fio",
121	            new BigDecimal("199.90"), new BigDecimal("0.25"), 5, false));
122	        productRepository.save(new Product("MEI-001", "Meia esportiva",
123	            new BigDecimal("19.90"), new BigDecimal("0.10"), 100, false));
124	        productRepository.save(new Product("JAQ-001", "Jaqueta corta-vento",
125	            new BigDecimal("389.90"), new BigDecimal("0.80"), 3, false));
126	    }
127	
128	    @Test
129	    void example1() {
130	        when(transLogClient.getQuote("01310100", 1800, "EXP"))
131	            .thenReturn(new TransLogClient.QuoteResult(3310, 41));
132	
133	        OrderRequest request = new OrderRequest(
134	            new OrderRequest.CustomerInfo("12345678909", "ana@exemplo.com"),
135	            List.of(
136	                new OrderRequest.ItemInfo("CAM-001", 2),
137	                new OrderRequest.ItemInfo("TEN-001", 1)
138	            ),
139	            "01310100",
140	            Region.NORTH,
141	            ShippingMethod.EXPRESS,
142	            CouponCode.WELCOME10,
143	            PaymentMethod.PIX,
144	            1,
145	            ClubTier.BRONZE
146	        );
147	
148	        OrderSummary summary = checkoutService.calculateSummary(request);
149	
150	        assertEquals(new BigDecimal("409.70"), summary.productsSubtotal().value());
151	        assertEquals(new BigDecimal("40.97"), summary.couponDiscount().value());
152	        assertEquals(new BigDecimal("33.10"), summary.shippingCost().value());
153	        assertEquals(5, summary.deliveryDays());
154	        assertEquals(new BigDecimal("10.24"), summary.insurance().value());
155	        assertEquals(new BigDecimal("0.00"), summary.paymentAdjustment().value());
156	        assertEquals(new BigDecimal("412.07"), summary.finalTotal().value());
157	        assertEquals(1, summary.installments());
158	        assertEquals(new BigDecimal("412.07"), summary.installmentAmount().value());
159	        assertEquals(new BigDecimal("0.00"), summary.nextPurchaseCredit().value());
160	        assertFalse(summary.gift());
161	    }
162	
163	    @Test
164	    void example2() {
165	        when(transLogClient.getQuote("01310100", 1800, "STD"))
166	            .thenReturn(new TransLogClient.QuoteResult(1560, 168));
167	
