186	        assertEquals(new BigDecimal("0.00"), summary.couponDiscount().value());
187	        assertEquals(new BigDecimal("15.60"), summary.shippingCost().value());
188	        assertEquals(7, summary.deliveryDays());
189	        assertEquals(new BigDecimal("6.15"), summary.insurance().value());
190	        assertEquals(new BigDecimal("30.55"), summary.paymentAdjustment().value());
