 57	package com.loja.integration;
 58	
 59	import org.springframework.beans.factory.annotation.Value;
 60	import org.springframework.stereotype.Component;
 61	import org.springframework.web.client.RestClient;
 62	
 63	import java.time.Duration;
 64	
 65	@Component
 66	public class TransLogClient {
 67	
 68	    private final String baseUrl;
 69	    private final RestClient restClient;
 70	
 71	    public TransLogClient(@Value("${translog.url}") String baseUrl,
 72	                          @Value("${translog.timeout}") int timeoutMs) {
 73	        this.baseUrl = baseUrl;
 74	        this.restClient = RestClient.builder()
 75	            .baseUrl(baseUrl)
 76	            .build();
 77	    }
 78	
 79	    public QuoteResult getQuote(String zipCode, int weightGrams, String service) {
 80	        try {
 81	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
 82	                baseUrl, zipCode, weightGrams, service);
 83	
 84	            QuoteResponse response = restClient.get()
 85	                .uri(url)
 86	                .retrieve()
 87	                .body(QuoteResponse.class);
 88	
 89	            if (response == null || response.error != null) {
 90	                return null;
 91	            }
 92	
 93	            return new QuoteResult(response.priceCents, response.etaHours);
 94	        } catch (Exception e) {
 95	            throw new TransLogUnavailableException("TransLog is unavailable", e);
 96	        }
 97	    }
 98	
 99	    private static class QuoteResponse {
100	        public Integer priceCents;
101	        public Integer etaHours;
102	        public String error;
103	    }
104	
105	    public record QuoteResult(Integer priceCents, Integer etaHours) {}
106	}
  1	package com.loja.service;
  2	
  3	import com.loja.domain.*;
  4	import com.loja.dto.OrderRequest;
  5	import com.loja.exception.ErrorCode;
  6	import com.loja.integration.TransLogUnavailableException;
  7	import com.loja.repository.OrderRepository;
  8	import com.loja.repository.ProductRepository;
  9	import com.loja.service.club.ClubTierStrategy;
 10	import com.loja.service.coupon.CouponStrategy;
 11	import com.loja.service.payment.PaymentStrategy;
 12	import com.loja.service.shipping.ShippingStrategy;
 13	import org.springframework.stereotype.Service;
 14	import org.springframework.transaction.annotation.Transactional;
 15	
 16	import java.math.BigDecimal;
 17	import java.util.*;
 18	import java.util.stream.Collectors;
 19	
 20	@Service
 21	public class CheckoutService {
 22	
 23	    private final ProductRepository productRepository;
 24	    private final OrderRepository orderRepository;
 25	    private final InsuranceService insuranceService;
 26	    private final Map<CouponCode, CouponStrategy> couponStrategies;
 27	    private final Map<ShippingMethod, ShippingStrategy> shippingStrategies;
 28	    private final Map<PaymentMethod, PaymentStrategy> paymentStrategies;
 29	    private final Map<ClubTier, ClubTierStrategy> clubStrategies;
 30	
 31	    public CheckoutService(
 32	            ProductRepository productRepository,
 33	            OrderRepository orderRepository,
 34	            InsuranceService insuranceService,
 35	            List<CouponStrategy> coupons,
 36	            List<ShippingStrategy> shippings,
 37	            List<PaymentStrategy> payments,
 38	            List<ClubTierStrategy> clubs) {
 39	        this.productRepository = productRepository;
 40	        this.orderRepository = orderRepository;
 41	        this.insuranceService = insuranceService;
 42	        this.couponStrategies = coupons.stream()
 43	            .collect(Collectors.toMap(CouponStrategy::getCode, c -> c));
 44	        this.shippingStrategies = shippings.stream()
 45	            .collect(Collectors.toMap(ShippingStrategy::getMethod, s -> s));
 46	        this.paymentStrategies = payments.stream()
 47	            .collect(Collectors.toMap(PaymentStrategy::getMethod, p -> p));
 48	        this.clubStrategies = clubs.stream()
 49	            .collect(Collectors.toMap(ClubTierStrategy::getTier, c -> c));
 50	    }
 51	
 52	    @Transactional(readOnly = true)
 53	    public OrderSummary calculateSummary(OrderRequest request) {
 54	        validateRequest(request);
 55	
